; NAKA Widget Dispatch Parameters & Instruction Data
; UI widget subsystem: parameter templates, bitmap descriptors,
; field configurations, and bytecode instruction data for the widget engine

;  17 x 18-byte sound-parameter descriptors, 0xEE0010-0xEE0142.
;  The record structure and every field name are in
;  audio/sndparam_records/run_ee0010.c + sndparam_types.h, which
;  `clang -target tlcs900` compiles to the byte-identical blob below.
;  The 37 labels are kept as absolute equates so the pointer table in
;  ui_widgets/widget_dispatch.s still resolves them.
SndParamRun_EE0010:
	.incbin "includes/generated/sndparam_run_ee0010.bin"
NakaInst_Param_Bitmap80 = SndParamRun_EE0010 + 0
NakaInst_Param_Field02 = SndParamRun_EE0010 + 2
