; -----------------------------------------------------------------------------
; Seven small arrays read by audio/dsp_config_sysex.s through positional
; names (ToneKit_VoiceDispatch_Table_0x31C .. _0x348).
; -----------------------------------------------------------------------------
; byte[n], read by DSPCfg_Data_001 (0xFDC448: `add xbc,xwa / ld l,(xbc)`).  No
; call of DSPCfg_Data_001 was found (call/calr/jp/jr target scan of the v10
; ELF disassembly), so the index range and purpose are not established.
DspCfg_Data001_ByteTable:	.byte 0, 0, 0, 0
; byte[n], read by DSPCfg_Data_002 (0xFDC464), same shape; no caller found
; by the same scan; purpose not established.
DspCfg_Data002_ByteTable:	.byte 1, 1, 1, 1
; DSP block index 0..5 -> object code.  DSPCfg_LookupMidiMap (0xFDBFC6) passes
; byte[block] to VoiceData_LookupPtrByIndex; DSPCfg_ResolveParamToSlot_Range49..4E
; call it with the block of the 0x49xx..0x4Exx parameter id; and
; DSPCfg_WriteParamFull / DSPCfg_WriteAllSlots_Direct post byte[block] as the
; SwbtWr event code through AssswbWr.  The SwbtWr bank-2 lists of exactly
; these five codes (0x61, 0x63, 0x64, 0x65, 0x66) contain EffEdit_DSPConfigBlock;
; code 0x62's list does not.  The values happen to be ASCII 'a','c','e','f','d';
; they are codes, not text.  0xFF = no object.
DspBlock_ObjectCode_Table:	.byte 0x61, 0x63, 0x65, 0x66, 0x64, 0xff
; parameter id 0x4900+i (i = 0..7) -> signed byte, stored through the caller's
; pointer by DSPCfg_DecodeParamIdRange (0xFDC504: `sub xwa,0x4900`, `cp xwa,7`,
; `add xwa,<this>`, `ld c,(xwa) / exts bc`).
DspParamId4900_ByteMap:	.byte 0, 2, 6, 3, 8, 5, 9, 7
; u16[i], read by DSPCfg_ResolveWithFallback (0xFDC710) as `add xwa,xwa` index
; then `sll bc,8`; purpose of the resulting value not established.
DspCfg_ResolveFallback_WordTable:	.short 0, 2, 4, 5, 3
; switch table: u16 offset per op letter 'a'..'f' (`sub wa,97`, `cp wa,5`),
; jumped to as 0xFDCCD3 + offset by the code after DSPCfg_Data_ParamDispatch
; (`jp_rr 8, xix, wa`).  The targets have no labels yet, so the offsets stay
; numeric: 0xFDCCD3, 0xFDCCDC, 0xFDCCE3, 0xFDCCEC, 0xFDCCF5, 0xFDCCFE (v10).
DspCfg_OpLetter_JumpOffsets:	.short 0, 9, 16, 25, 34, 43
; switch table: u16 offset from AssSwb_SwapEntriesAndDispatch, 21 entries,
; used by DspConfig_EventDispatch (0xFDD29D: index = type-1 for 0..8, or
; type-1-0x12 for 9..20; `add bc,bc`, `ldw_sri`, `jp_ind`).  Offset 0 is the
; default (AssSwb_SwapEntriesAndDispatch itself); the other targets have no
; labels yet.
DspConfig_EventDispatch_JumpOffsets:	.short 285, 328, 0, 436, 501, 878, 0
	.short 0, 921, 0, 0, 0, 0, 8
	.short 51, 0, 94, 0, 0, 0, 151
; =============================================================================
; DSP EFFECT PARAMETER-WRITE RECORDS  (0xEE63BA-0xEE75F5, 59 lists, 4668 bytes)
; =============================================================================
; One list per DSP EFFECT NUMBER (the index of DspEffectName_PtrTable, 0xE32A7A;
; names below come from that table).  Record k of a list describes how
; parameter k of the effect is written to the DSP; the same effect number
; indexes three parallel 100-entry tables:
;   0xEE5FE0  u8 x100   parameter count  (DSPCfg_GetSlotCount 0xFDC456)
;   0xEE6044  u32 x100  -> {min,max,param_id} u16 x3 per parameter
;                        (DSPCfg_LookupAndExtract 0xFDC41D, `mul wa,6`)
;   0xEE75F6  u32 x100  -> the record list below (DspFxRecListPtrTable)
;
; Record layout, from the readers in audio/dsp_config_sysex.s:
;   +0  u16 BIG-endian total length, header and terminator included
;       (DSPCfg_PackAddress 0xFDC14A: next = rec + (rec[0]<<8 | rec[1]))
;   +2  op letter            (DSPCfg_FindSlot63 0xFDC472 `cp (xwa+2),0x63`;
;                             DSPCfg_WriteParam 0xFDC013 special-cases
;                             'v' 'p' 'g' 'd')
;   +3  op operands          (DSPCfg_ExtractFieldSingle 0xFDBFFC reads +4,
;                             DSPCfg_ExtractFieldPair 0xFDBFD5 reads +4/+5)
;       The body +2..len-2 is 1..8 equal-sized sub-entries, EACH headed by
;       the same op letter (measured; one line per sub-entry below).
;   +len-1  0x7A 'z'         terminator
; A list ends with one 0xF0 byte (DSPCfg_PackAddress stops on rec[0]==0xF0)
; and is padded with 0xFF to an even address.
;
; Pinned by scripts/generators/gen_dsp_effect_records.py --probe: every list
; walks with 'z' on every record, its record count equals the count byte,
; and lists + terminators + pads partition this span with no byte left over.
; [INFERENCE] The op letter names the kind of DSP write, not the parameter:
; paired with the range records, '!' falls on param id 0x03 in 38 of 38
; records and 'c' on 0x01/0x02 in 54 of 59 -- DspParamName_Table's REV SEND
; and VOLUME names (the probe prints the full letter/id concordance; ids
; read as DspParamName_Table indexes is the inference).  Effects that share an
; algorithm share a letter string: ROCK ROTARY (15) and ROTARY SPEAKER (53)
; are both 'abfjjiifjjiicf!t', the 12 reverbs 16-27 are all 'ugvfc'.
; Open question for the DSP work: what each letter's operands do on the DSP
; side -- they include 24-bit big-endian coefficients such as 0x266666 and
; 0x400000 (cf. the sub-CPU DSP_EffNN_* blocks in v142/subcpu).
; Byte-identical in v7, v9 and v10.
; =============================================================================
; effect 32 DISTORTION -- 5 parameter-write records (count byte 0xEE5FE0+32);
; reached through DspFxRecListPtrTable entry 32 (DSPCfg_FindSlot63 & co.)
DspFxRecs_32_Distortion:
	.byte 0x00, 7,	'a', 0x00
	.byte		'a', 0x01, 'z'
	.byte 0x00, 7,	'b', 0x00
	.byte		'b', 0x01, 'z'
	.byte 0x00, 6,	'c', 0x00, 0x00, 'z'
	.byte 0x00, 11,	'!', 0x00, 0x00, 0x00, 0x00, 0x26, 0x66, 0x66, 'z'
	.byte 0x00, 6,	't', 0x00, 0x01, 'z'
	.byte 0xf0	; end of list
