; and subtracted from RAM 0xCEAA: SoundFX_Handler_9 (0xFE933D) uses +0/+1,
; SoundFX_Handler_10 (0xFE9360) +2/+3, SoundFX_Handler_11 (0xFE9383) +4/+5.
